export const settlementCashDefinitions={
  settlementCashPlanning:{title:'Put an assumed sale, bank receipt and one bill on a fictional calendar',fields:[
    ['settleOpening','Opening spendable bank cash (CAD)',1000,0,100000,100],
    ['settleProceeds','Assumed net sale proceeds, entered independently (CAD)',5000,0,1000000,100],
    ['settleBill','One scheduled bill paid from this bank account (CAD)',4000,0,1000000,100],
    ['settleDueDay','Bill day in the 14-day calendar',10,1,14,1],
    ['settleTradeDay','Assumed executed sale day: first-week Mon=1 to Fri=5',5,1,5,1],
    ['settleBusinessDays','Assumed business days after execution to settlement',1,1,3,1],
    ['settleBankWait','Assumed post-settlement business days until bank receipt',2,0,6,1],
    ['settleClosures','Extra fictional closed weekdays in week 2, starting Day 8',0,0,3,1]
  ]}
};
const weekdays=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
export const settlementDayName=day=>'Day '+day+' · '+weekdays[((day-1)%7+7)%7];
export function settlementOpenDay(day,closures=0){return ((day-1)%7+7)%7<5&&!(day>=8&&day<8+closures);}
export function advanceSettlementDays(start,count,closures=0){
  let day=start,remaining=count;
  while(remaining>0){day++;if(settlementOpenDay(day,closures))remaining--;}
  return day;
}
export function settlementCashCalendar(input){
  const settlement=advanceSettlementDays(input.settleTradeDay,input.settleBusinessDays,input.settleClosures),arrival=advanceSettlementDays(settlement,input.settleBankWait,input.settleClosures),required=Math.max(0,input.settleBill-(arrival<=input.settleDueDay?input.settleProceeds:0)),additional=Math.max(0,required-input.settleOpening);
  const rows=Array.from({length:15},(_,day)=>({x:day,label:day===0?'Opening before Day 1':settlementDayName(day),value:input.settleOpening+(arrival<=day?input.settleProceeds:0)-(input.settleDueDay<=day?input.settleBill:0),open:day>0?settlementOpenDay(day,input.settleClosures):false}));
  return {settlement,arrival,required,additional,rows,ending:rows.at(-1).value,minimum:Math.min(...rows.map(r=>r.value)),pendingAtEnd:arrival>14?input.settleProceeds:0};
}
export function settlementReceiptStage(input,day){
  const p=settlementCashCalendar(input),amount=input.settleProceeds;
  return {planned:day<input.settleTradeDay?amount:0,receivable:day>=input.settleTradeDay&&day<p.settlement?amount:0,offBank:day>=p.settlement&&day<p.arrival?amount:0,received:day>=p.arrival?amount:0};
}
export function settlementCashResult(kind,input){
  if(kind!=='settlementCashPlanning')throw Error('Unknown settlement cash topic.');
  const p=settlementCashCalendar(input),stages=day=>{const r=settlementReceiptStage(input,day);return [r.receivable,r.offBank,r.received];},milestones=[{label:'After executed sale · '+settlementDayName(input.settleTradeDay),values:stages(input.settleTradeDay)},{label:'After settlement · '+settlementDayName(p.settlement),values:stages(p.settlement)},{label:'At bank receipt · '+settlementDayName(p.arrival),values:stages(p.arrival)}];
  const note='Settlement occurs on '+settlementDayName(p.settlement)+' and the assumed bank receipt on '+settlementDayName(p.arrival)+(p.arrival>14?' (after the displayed bank ledger). ':'. ')+'An entirely fictional calendar: Day 1 is Monday; weekends are closed, plus the entered number of consecutive fictional weekdays beginning Day 8. One shared open-day calendar is used for settlement and bank processing, although real calendars and cutoffs can differ. The executed sale is assumed completed on the selected first-week weekday; no order is placed or guaranteed. Positive business-day waits exclude their starting day; zero post-settlement wait means an explicitly assumed same-day bank receipt. Receipts are available before the bill within a day. The bill occurs on its entered day even on a closed day; no automatic due-date shift is modeled. Negative bank positions are unfunded scheduled payments, not an available overdraft. Net sale proceeds are an independent input; security prices, fees, taxes, account eligibility, holds and registered-account consequences are not calculated. Settlement alone does not promise withdrawal eligibility or bank availability. '+(p.arrival>14?'At Day 14, CAD '+p.pendingAtEnd.toFixed(2)+' of entered proceeds has not reached the bank; the modeled receipt date remains beyond the window even when the proceeds input is zero. ':'The modeled receipt date is within the displayed window. ');
  return {metrics:[['Assumed receipt in the spending bank',p.arrival,'integer',settlementDayName(p.arrival)+(p.arrival>14?' · after Day 14':'')],['Additional opening bank cash needed for this bill',p.additional,'money'],['Scheduled bank cash after Day 14',p.ending,'money']],note,charts:[
    {id:'settlement-bank-ledger',type:'line',title:'A later receipt cannot retroactively fund an earlier bill',unit:'money',unitLabel:'CAD scheduled in the bank account at each day-end',xLabel:'Day in the fictional calendar',xTicks:[0,4,7,10,14].map(value=>({value,label:value===0?'Opening':'Day '+value})),series:[{name:'Bank cash / unfunded scheduled position',step:true,rows:p.rows.map(({x,label,value})=>({x,label,value}))}],note:'The opening point is immediately before Day 1. The sale amount enters this bank ledger once, only on its assumed bank-receipt day; the bill leaves once on its entered day. A negative point is the earlier payment amount that still needs funding. At the defaults, receipt and the bill are both on Day 10, so receipt-first posting funds the bill. In that default case, adding one fictional closure shifts receipt to Day 11 and creates a CAD 3,000 earlier gap despite the same CAD 2,000 endpoint. Other household bills and receipts are outside this partial plan.'},
    {id:'settlement-proceeds-stages',type:'stackbar',title:'Follow the same proceeds through three successive processing snapshots',unit:'money',unitLabel:'CAD of the same assumed sale receipt, before allocating it to household spending',seriesNames:['Unsettled receivable','Settled proceeds still off bank','Receipt in spending bank'],rows:milestones,note:'These rows are separate snapshots of the same proceeds, not three assets or three receipts to add. The middle category includes broker processing and transfer transit; it does not promise that funds remain a withdrawable brokerage balance throughout that interval. A zero post-settlement wait collapses the middle interval to the same day, rather than creating extra cash. This chart traces the gross entered receipt before its bill allocation, while the separate bank ledger deducts the bill. A sale exchanges an investment for proceeds; it does not create this amount as earned income.'},
    {id:'settlement-fictional-open-days',type:'heatmap',title:'Read the open-day assumptions before counting a wait',unit:'integer',unitLabel:'1 = open model business day; 0 = closed model day',columns:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],rows:[0,1].map(week=>({label:'Days '+(week*7+1)+'–'+(week*7+7),values:Array.from({length:7},(_,i)=>settlementOpenDay(week*7+i+1,input.settleClosures)?1:0)})),note:'This is a fictional two-week calendar, not an actual 2026 holiday calendar. Dark cells are open (1); pale cells are closed (0). The first week contains the selectable executed-trade dates. Extra closures, if entered, start at Day 8 in week two, so they cannot silently put the assumed execution on a closed day. Actual settlement, broker and bank calendars, time zones, cutoffs and posting order must be checked separately.'},
    {id:'settlement-weekday-closure',type:'groupbar',title:'A Friday execution can make one later closure matter',unit:'integer',unitLabel:'Bank-receipt day number; Day 1 is the fictional Monday',seriesNames:['Weekends only','One fictional closure on Day 8'],rows:[1,2,3,4,5].map(settleTradeDay=>({label:weekdays[settleTradeDay-1]+' execution'+(settleTradeDay===input.settleTradeDay?' · selected weekday':''),values:[0,1].map(settleClosures=>settlementCashCalendar({...input,settleTradeDay,settleClosures}).arrival)})),note:'This fixed comparison replaces the trade day and closure count while retaining the selected settlement and post-settlement waits. It always compares zero and one Day-8 closure, even if the main closure control is two or three. Longer bars mean a later calendar day of bank receipt, not more money or a probability. An arrival after Day 14 remains on its actual model day rather than being clipped into the bank ledger.'},
    {id:'settlement-earlier-cash-grid',type:'heatmap',title:'Find the opening-cash gap under different execution and processing assumptions',unit:'money',unitLabel:'Additional opening bank cash required for the selected bill',columns:['0 bd','1 bd','2 bd','3 bd','6 bd'],rows:[1,2,3,4,5].map(settleTradeDay=>({label:weekdays[settleTradeDay-1]+' trade',values:[0,1,2,3,6].map(settleBankWait=>settlementCashCalendar({...input,settleTradeDay,settleBankWait}).additional)})),note:'Rows replace the first-week executed-trade weekday; columns replace the post-settlement wait until bank receipt in model business days. Opening cash, proceeds, bill/day, settlement count and entered closures stay fixed. A zero wait is an assumed same-day bank receipt after settlement, not a guaranteed broker service. Each cell is a separate timing scenario with no assigned probability. Receipt-before-bill posting applies if both fall on the same day.'}
  ]};
}
